import{z as m,x as p,o as n,c as E,q as d,j as i,D as t,d as r,s,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"中国剩余定理","description":"","frontmatter":{"title":"中国剩余定理","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/crt.md","filePath":"cs/crt.md","lastUpdated":1791063341000}'),A={name:"cs/crt.md"};function _(B,a,u,h,b,q){const o=p("Mermaid");return n(),E("div",null,[a[2]||(a[2]=d('<h1 id="中国剩余定理" tabindex="-1">中国剩余定理 <a class="header-anchor" href="#中国剩余定理" aria-label="Permalink to &quot;中国剩余定理&quot;">​</a></h1><div class="epigraph"><p>模两两互素时，同余方程组有唯一解模乘积；$\\mathbb{Z}/mn\\mathbb{Z}\\cong\\mathbb{Z}/m\\mathbb{Z}\\times\\mathbb{Z}/n\\mathbb{Z}$。RSA 的 $p,q$ 两侧运算由此合法。</p><footer>—— 据《孙子算经》；Gauss；Ireland and Rosen 整理</footer></div><p>上一课<a href="/cs/fermat-euler">欧拉定理</a> 在单个模上减指数。缺口是<strong>联立</strong>：已知 \\(x\\bmod p\\)、\\(x\\bmod q\\)，恢复 \\(x\\bmod pq\\)。CRT。构造：\\(x=\\sum a_i M_i y_i\\)，\\(M_i=M/n_i\\)，\\(y_i=M_i^{-1}\\bmod n_i\\)。本课互素情形；一般模用 gcd 条件。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>环同构：一对 \\((x\\bmod m,x\\bmod n)\\) 对应唯一 \\(x\\bmod mn\\)。乘法、加法分量做。RSA 解密可在模 \\(p\\) 与模 \\(q\\) 上做模幂再合并，快约四倍（指数更短）。证明 \\(a^{k\\lambda(n)}\\equiv a\\pmod{pq}\\) 也对非互素 \\(a\\) 成立时，走两边再 CRT。</p><p>非互素：方程组可能无解。本课主线两两互素。</p><h3 id="不是「哈希到小整数」" tabindex="-1">不是「哈希到小整数」 <a class="header-anchor" href="#不是「哈希到小整数」" aria-label="Permalink to &quot;不是「哈希到小整数」&quot;">​</a></h3><p>CRT 是同构，信息不少。把消息拆成模 \\(p\\) 与模 \\(q\\) 仍保密——因为 \\(p,q\\) 是私钥。公开 \\(n\\) 上不能拆。</p><p><span class="marginnote">《孙子算经》物不知数。Gauss 《算术探究》。Knuth 卷 2。密码实现的 Garner 算法是 CRT 的一种组织，点名。</span></p><p><span class="marginnote">直觉类比：CRT 就是《孙子算经》的「物不知数」——「某数除以 3 余 2、除以 5 余 3、除以 7 余 2，问数几何」。只要模两两互素，这些余数就能在 \\(3\\times5\\times7=105\\) 以内唯一锁定那个数，不多不少。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>解 \\(x\\equiv 2\\pmod 3\\)、\\(x\\equiv 3\\pmod 5\\)、\\(x\\equiv 2\\pmod 7\\)。写出同构对乘法：模 \\(15\\) 的零因子对应一侧为 \\(0\\)。指出：求 \\(\\varphi(pq)\\) 需要 \\(p,q\\)，与 CRT 拆运算是同一秘密的两面。</p>',12)),(n(),i(l,null,{default:t(()=>[s(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SYS%5B%22x%20mod%20m%2C%20x%20mod%20n%22%5D%20--%3E%20CRT%5B%22%E4%BA%92%E7%B4%A0%20%E2%87%92%20%E5%94%AF%E4%B8%80%20x%20mod%20mn%22%5D%0A%20%20CRT%20--%3E%20ISO%5B%22%E7%8E%AF%E5%90%8C%E6%9E%84%E5%88%B0%E4%B9%98%E7%A7%AF%22%5D%0A%20%20ISO%20--%3E%20RSA%5B%22%E4%B8%A4%E4%BE%A7%E6%A8%A1%E5%B9%82%E5%86%8D%E5%90%88%E5%B9%B6%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"数字实例：RSA 解密的指数 \\(d\\) 与 \\(n\\) 同量级（2048 位里约 2048 位）；拆到 \\(p,q\\) 两侧后，\\(d_p,d_q\\) 只有约 1024 位，模乘的数也小一半。模幂代价随位数超线性涨，两侧合计比原来快约四倍。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"有了同构，下一课才能安心谈「先当环、再当域」：模素数是域，模 \\(pq\\) 只是环。CRT 把环拆成域的积。后课有限域 \\(\\mathrm{GF}(2^n)\\) 是另一构造，不是 CRT。",-1)),a[6]||(a[6]=e("p",null,"Coppersmith、Hastad 广播攻击用 CRT 组合同一指数的密文，本课不进攻击细节。",-1)),a[7]||(a[7]=e("p",null,"一般形式：模 \\(n_i\\) 不必互素，当 \\(a_i\\equiv a_j\\pmod{\\gcd(n_i,n_j)}\\) 才有解，解模 \\(\\mathrm{lcm}\\)。Garner 算法按前缀逐步合并，实现常用。RSA-CRT 私钥含 \\(d_p,d_q\\)；侧信道若漏出一侧余数会危及分解，属实现，本课只给同构。",-1)),(n(),i(l,null,{default:t(()=>[s(o,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E8%A7%A3%E5%AF%86%3A%20%E6%B1%82%20c%5Ed%20mod%20n%22%5D%20--%3E%20SP%5B%22%E6%8B%86%E4%BE%A7%E4%B8%80%3A%20m_p%20%3D%20c%5E%7Bd_p%7D%20mod%20p%22%5D%0A%20%20C%20--%3E%20SQ%5B%22%E6%8B%86%E4%BE%A7%E4%BA%8C%3A%20m_q%20%3D%20c%5E%7Bd_q%7D%20mod%20q%22%5D%0A%20%20SP%20--%3E%20MG%5B%22%E6%8C%89%20CRT%20%E5%90%88%E5%B9%B6%E4%B8%A4%E4%B8%AA%E4%BD%99%E6%95%B0%22%5D%0A%20%20SQ%20--%3E%20MG%0A%20%20MG%20--%3E%20M%5B%22%E5%BE%97%E5%88%B0%E6%98%8E%E6%96%87%20m%20mod%20n%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=d('<p><span class="marginnote">常见误区：初学者容易把 CRT 当成「把大数压成小数」的有损压缩。实际上它是无损同构——一组互素模下的余数不多不少正好对应大模下的一个余数，信息一点没丢，所以才能拆开算完再原样合回去。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证环论的一般中国剩余，不引入赋值。不写 RSA 实现代码。后课默认：互素模系可拆可合。下一课群环域的名字。</p><p>同构把「一组小模余数」与「一个大模余数」当成同一元素的两种写法。RSA 用它加速；安全上 \\(p,q\\) 仍须保密。非互素方程组可能无解，主线用两两互素。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>两两互素：方程组唯一解模乘积；环同构到乘积环。</li><li>RSA 用它把模 \\(n\\) 运算拆到 \\(p,q\\)。</li><li>非互素则可能无解。</li><li>出处：《孙子算经》；Gauss；Ireland and Rosen。</li></ul>',6))])}const C=m(A,[["render",_]]);export{T as __pageData,C as default};
